const CM_J=(n,x)=>{let s=0,f=1;for(let i=1;i<=n;i++)f*=i;let fk=1,fnk=f;for(let k=0;k<40;k++){if(k>0){fk*=k;fnk*=(n+k)}s+=((k%2)?-1:1)/(fk*fnk)*Math.pow(x/2,2*k+n)}return s};
